package main

import (
	"fmt"
	"os/exec"
	"strings"
)

func main() {
	// Example of capturing and formatting compiler error messages
	cmd := exec.Command("tsc", "--noEmit", "example.ts")
	var compilerError strings.Builder
	cmd.Stderr = &compilerError
	err := cmd.Run()

	if err != nil {
		fmt.Println("Compilation failed with error:")
		fmt.Println(strings.TrimSpace(compilerError.String()))
	} else {
		fmt.Println("Compilation succeeded")
	}
}
